def comp(g,bg):
    s={(r,c,g[r][c]) for r in range(len(g)) for c in range(len(g[0])) if g[r][c]!=bg}
    objs=[]
    seen=set(); 
    while s-seen:
        cell=s.pop(); stack=[cell]; comp_=set()
        while stack:
            r,c,v=stack.pop()
            key=(r,c,v)
            if key in comp_: continue
            comp_.add(key)
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    n=(r+dr,c+dc,v)
                    if n in s-seen: s.discard(n); comp_.add(n); stack.append(n)
        objs.append(comp_)
    return objs
